-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (9348, 37, 'Landesmittel bzw. Investitionsprogramm für Sanierung und Neubau von Sportstätten aufstocken (Land)', 'Setzt direkt am Sanierungsstau an; Studien zeigen, dass Sportplätze und Bäder die Vereinsteilnahme stützen. Landesmittel sind aber klein gegenüber dem Rückstand in Milliardenhöhe und hängen vom Haushalt ab.', 'belegt', 'https://www.bisp-surf.de/Record/PU201407006674', 'land', null, true, 'blind'),
  (9349, 37, 'Bestehende Sportstättenförderung des Landes fortführen (Land)', 'Sichert die bisherige Förderung ab und ist leicht umsetzbar; zusätzliche Mittel gegen den wachsenden Rückstand sind damit nicht verbunden.', 'offen', null, 'land', null, true, 'blind'),
  (9350, 37, 'Planung, Datengrundlage und schnellere Förder- und Genehmigungsverfahren für Sportstättenbau (Land)', 'Kommunen wünschen weniger Bürokratie in Förderprogrammen, und bessere Daten lenken Mittel gezielter. Ohne zusätzliches Geld bleibt der Abbau des Sanierungsstaus aber begrenzt; Wirkung kaum untersucht.', 'offen', 'https://kommunal.de/sportstaetten-sanierung-kommunen-finanzen', 'land', null, true, 'blind'),
  (9351, 37, 'Prioritäten bei Sportstätteninvestitionen setzen (Bestand, Schulsport, Bäder) (Land)', 'Kann knappe Mittel auf den Bestand lenken und ist einfach umsetzbar; ändert aber nichts an der Höhe der verfügbaren Mittel.', 'offen', null, 'land', null, true, 'blind'),
  (9352, 37, 'Sportflächen bei Neubauvorhaben einplanen bzw. vorschreiben (Land)', 'Schafft zusätzliche, meist offene Sportflächen bei Neubauten; der Rückstand bei bestehenden Hallen und Bädern bleibt unberührt. Verpflichtungen für Investoren brauchen Bauplanungsrecht und Verträge.', 'offen', null, 'land', null, true, 'blind'),
  (9353, 37, 'Öffentliche Sportstätten für Vereine kostenfrei oder stark vergünstigt nutzbar machen (Land)', 'Sportstättenkosten bestimmen laut Panelstudie die Höhe der Vereinsbeiträge, daher entlastet freie Nutzung spürbar. Die Kosten tragen aber Kommunen, deren Sportbetriebe oft schon Verluste haben; Ausgleich durch das Land nötig.', 'belegt', 'https://www.bisp-surf.de/Record/PU202008006689', 'land', null, true, 'blind'),
  (9354, 37, 'Bestehende gebührenfreie Nutzung von Sportstätten und Bädern für Vereine beibehalten (Land)', 'Verhindert Beitragserhöhungen durch neue Nutzungsgebühren, die laut Studien auf Beiträge durchschlagen; bringt gegenüber heute aber keine zusätzliche Entlastung.', 'belegt', 'https://www.bisp-surf.de/Record/PU202008006689', 'land', null, true, 'blind'),
  (9355, 37, 'Energetische Sanierung von Bädern und Eishallen zur Senkung der Betriebskosten (Land)', 'Messungen in Pilotbädern zeigen deutliche Einsparungen bei Wärme und Strom und senken so Betriebsverluste. Hohe Investitionen nötig; Wirkung erst nach Jahren.', 'belegt', 'https://www.energiezukunft.eu/bauen/bauzukunft/energieeffizient-im-spa', 'land', null, true, 'blind'),
  (9356, 37, 'Vereinspauschalen bzw. Grundförderung des Landes für Sportvereine erhöhen und dynamisieren (Land)', 'Mehr und breitere Einnahmen gehen laut Panelstudie mit niedrigeren Beiträgen einher und verbessern die Finanzlage der Vereine. Dauerhafte Mehrausgaben belasten den Landeshaushalt.', 'belegt', 'https://www.bisp-surf.de/Record/PU202008006689', 'land', null, true, 'blind'),
  (9357, 37, 'Bestehende Förderung des Landessportbunds langfristig fortführen (Land)', 'Gibt Vereinen Planungssicherheit und ist leicht umsetzbar; zusätzliche Mittel gegen gestiegene Kosten sind damit nicht verbunden.', 'offen', null, 'land', null, true, 'blind'),
  (9358, 37, 'Landesförderung für Personal in Vereinen (Übungsleiter, Trainer, Hauptamt, Weiterbildung) (Land)', 'Kosten für Trainer und Übungsleiter treiben laut Panelstudie die Beiträge; Zuschüsse entlasten Vereine direkt. Umfang meist unbestimmt, Finanzierung aus dem Landeshaushalt nötig.', 'belegt', 'https://www.bisp-surf.de/Record/PU202008006689', 'land', null, true, 'blind'),
  (9359, 37, 'Für höhere steuerfreie Übungsleiter- und Ehrenamtspauschalen eintreten (Land)', 'Kann Ehrenamt etwas attraktiver machen, eine Wirkung auf das Engagement ist aber nicht belegt; die Pauschalen wurden 2026 bereits erhöht. Regelt nur der Bund, das Land kann sich nur einsetzen.', 'offen', null, 'land', null, true, 'blind'),
  (9360, 37, 'Anerkennung und Rahmenbedingungen für Ehrenamtliche verbessern (Ehrenamtskarte, Freistellung, Vereinbarkeit) (Land)', 'Würdigt Ehrenamt und erleichtert Engagement; Evaluationen zeigen Zufriedenheit der Karteninhaber, aber keinen Nachweis für mehr Engagement. Die Finanzlage der Vereine ändert sich kaum.', 'offen', 'https://www.baden-wuerttemberg.de/de/service/presse/pressemitteilung/pid/erprobung-der-ehrenamtskarte-laeuft-erfolgreich', 'land', null, true, 'blind'),
  (9361, 37, 'Bürokratie für Vereine abbauen, Förderverfahren vereinfachen und Digitalisierung unterstützen (Land)', 'Bürokratie ist eine der größten Belastungen für Vereinsvorstände; Vereinfachung entlastet Ehrenamtliche. Viele Pflichten sind Bundes- oder EU-Recht, und die Wirkung auf die Vereinsfinanzen ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9362, 37, 'Kooperationen von Schulen und Kitas mit Sportvereinen fördern (Land)', 'Kann Vereinen Nachwuchs und bezahlte Ganztagsstunden bringen; belastet aber zugleich Ehrenamtliche, und die Wirkung auf die Vereinssituation ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9363, 37, 'Bundesprogramm zur Sanierung von Sportstätten und Schwimmbädern fortführen und ausbauen (Bund)', 'Setzt am Sanierungsstau an, und Sportstätten stützen die Vereinsteilnahme nachweislich. Der Bund finanziert solche Programme bereits; die Summen decken aber nur einen Teil des Rückstands.', 'belegt', 'https://www.bisp-surf.de/Record/PU201407006674', 'bund', null, true, 'blind'),
  (9364, 37, 'Steuerfreie Übungsleiter- und Ehrenamtspauschale erhöhen (Bund)', 'Vom Bund einfach umsetzbar und für Engagierte spürbar; eine Wirkung auf Zahl der Ehrenamtlichen oder Vereinsfinanzen ist nicht belegt, Vereine müssen die Zahlungen selbst aufbringen.', 'offen', null, 'bund', null, true, 'blind'),
  (9365, 37, 'Vereine bei Bürokratie, Haftung und Datenschutzpflichten entlasten (Bund)', 'Entlastet Vorstände bei häufig genannten Belastungen; Datenschutz ist zum Teil EU-Recht, und die Wirkung auf Vereinsfinanzen und Sportstätten ist kaum untersucht.', 'offen', null, 'bund', null, true, 'blind'),
  (9366, 37, 'Ehrenamt im Breitensport allgemein stärken und neue Engagierte gewinnen (Bund)', 'Zielt auf das Ehrenamt als Rückgrat der Vereine; konkrete Instrumente fehlen, und der Bund hat im Vereinssport nur begrenzte Hebel.', 'offen', null, 'bund', null, true, 'blind')
