insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (9367, 37, 11, null, 'Übungsleiter- und Ehrenamtspauschale spürbar erhöhen.', '{3703}', 9364, 1, 3, null, 'Vom Bund einfach umsetzbar und für Engagierte spürbar; eine Wirkung auf Zahl der Ehrenamtlichen oder Vereinsfinanzen ist nicht belegt, Vereine müssen die Zahlungen selbst aufbringen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=57', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9368, 37, 11, null, 'Vereinspaket für das Ehrenamt, das Bürokratie, Datenschutz und Haftungsfragen von Vereinen angeht.', '{3703}', 9365, 1, 2, null, 'Entlastet Vorstände bei häufig genannten Belastungen; Datenschutz ist zum Teil EU-Recht, und die Wirkung auf Vereinsfinanzen und Sportstätten ist kaum untersucht.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=57', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9369, 37, 11, null, 'Sportmilliarde für die kommende Wahlperiode bereitstellen (Verwendung im Text nicht genannt).', '{3701}', 9363, 2, 3, null, 'Setzt am Sanierungsstau an, und Sportstätten stützen die Vereinsteilnahme nachweislich. Der Bund finanziert solche Programme bereits; die Summen decken aber nur einen Teil des Rückstands.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=61', 'https://www.bisp-surf.de/Record/PU201407006674', 'belegt', '2026-10-11', false, true, 'blind'),
  (9370, 37, 11, 'BE', 'Investitionen in neue Schwimmbäder und Unterstützung der Sanierung von Sportanlagen in allen Bezirken', '{3701}', 9348, 2, 2, null, 'Setzt direkt am Sanierungsstau an; Studien zeigen, dass Sportplätze und Bäder die Vereinsteilnahme stützen. Landesmittel sind aber klein gegenüber dem Rückstand in Milliardenhöhe und hängen vom Haushalt ab.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=107', 'https://www.bisp-surf.de/Record/PU201407006674', 'belegt', '2026-10-11', false, true, 'blind'),
  (9371, 37, 11, 'BE', 'Vorhandene Sportstätten intelligent nutzen und Neubau nur dort, wo langfristig sinnvoll', '{3701}', 9351, 1, 3, null, 'Kann knappe Mittel auf den Bestand lenken und ist einfach umsetzbar; ändert aber nichts an der Höhe der verfügbaren Mittel.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=115', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9372, 37, 11, 'BE', 'Sanierungsstrategie, bessere Datengrundlage und beschleunigte Genehmigungen für Sportstätten', '{3701}', 9350, 1, 3, null, 'Kommunen wünschen weniger Bürokratie in Förderprogrammen, und bessere Daten lenken Mittel gezielter. Ohne zusätzliches Geld bleibt der Abbau des Sanierungsstaus aber begrenzt; Wirkung kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=111', 'https://kommunal.de/sportstaetten-sanierung-kommunen-finanzen', 'offen', '2026-10-11', false, true, 'blind'),
  (9373, 37, 11, 'BE', 'Unternehmensführung und -struktur der landeseigenen Bäder-Betriebe kritisch überprüfen', '{3702}', null, 1, 3, null, 'Eine Überprüfung der Bäderbetriebe kann Abläufe und Kosten verbessern; ob sich Verluste und Öffnungszeiten tatsächlich bessern, ist offen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=112', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9374, 37, 11, 'BE', 'Rechtssichere Rahmenbedingungen, damit gemeinnützige Sportvereine mit erneuerbaren Energien zusätzliche Einnahmen erzielen können', '{3703,3702}', null, 1, 1, null, 'Eigenstrom kann Energiekosten senken und Einnahmen bringen; die Gemeinnützigkeit regelt aber das Steuerrecht des Bundes, das Land kann wenig selbst tun.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=111', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9375, 37, 11, 'BE', 'Mehr Kooperationen zwischen Schulen und Sportvereinen ermöglichen und bürokratische Hürden abbauen', '{3703}', 9362, 1, 3, null, 'Kann Vereinen Nachwuchs und bezahlte Ganztagsstunden bringen; belastet aber zugleich Ehrenamtliche, und die Wirkung auf die Vereinssituation ist kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=113', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9376, 37, 11, 'BE', 'Vereine und Ehrenamt stärker anerkennen, bürokratische Hürden abbauen und Förderverfahren vereinfachen', '{3703}', 9361, 1, 3, null, 'Bürokratie ist eine der größten Belastungen für Vereinsvorstände; Vereinfachung entlastet Ehrenamtliche. Viele Pflichten sind Bundes- oder EU-Recht, und die Wirkung auf die Vereinsfinanzen ist kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=114', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9377, 37, 11, 'BE', 'Hauptamtliche Ansprechpartner und bedarfsgerechte Beratung für Vereine aufbauen', '{3703}', 9358, 2, 2, null, 'Kosten für Trainer und Übungsleiter treiben laut Panelstudie die Beiträge; Zuschüsse entlasten Vereine direkt. Umfang meist unbestimmt, Finanzierung aus dem Landeshaushalt nötig.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=114', 'https://www.bisp-surf.de/Record/PU202008006689', 'belegt', '2026-10-11', false, true, 'blind'),
  (9378, 37, 11, 'BE', 'Sportvereine bei Digitalisierung und beim Einsatz künstlicher Intelligenz unterstützen, um sie zu entlasten', '{3703}', 9361, 1, 3, null, 'Bürokratie ist eine der größten Belastungen für Vereinsvorstände; Vereinfachung entlastet Ehrenamtliche. Viele Pflichten sind Bundes- oder EU-Recht, und die Wirkung auf die Vereinsfinanzen ist kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=115', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9379, 37, 11, 'BE', 'Nutzung bezirklicher und landeseigener Flächen für das Ehrenamt kostenfrei ermöglichen', '{3702}', 9353, 2, 2, null, 'Sportstättenkosten bestimmen laut Panelstudie die Höhe der Vereinsbeiträge, daher entlastet freie Nutzung spürbar. Die Kosten tragen aber Kommunen, deren Sportbetriebe oft schon Verluste haben; Ausgleich durch das Land nötig.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=116', 'https://www.bisp-surf.de/Record/PU202008006689', 'belegt', '2026-10-11', false, true, 'blind'),
  (9380, 37, 11, 'MV', 'Mittel der Landessportförderung von 13 auf 20 Mio. Euro erhöhen; Sanierungsstau bei Sportstätten abbauen', '{3701}', 9348, 2, 2, null, 'Setzt direkt am Sanierungsstau an; Studien zeigen, dass Sportplätze und Bäder die Vereinsteilnahme stützen. Landesmittel sind aber klein gegenüber dem Rückstand in Milliardenhöhe und hängen vom Haushalt ab.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=83', 'https://www.bisp-surf.de/Record/PU201407006674', 'belegt', '2026-10-11', false, true, 'blind'),
  (9381, 37, 11, 'MV', 'Digitaler Sportstätten-Atlas erfasst Zustand und Sanierungsbedarf als Grundlage für Investitionsentscheidungen', '{3701}', 9350, 1, 3, null, 'Kommunen wünschen weniger Bürokratie in Förderprogrammen, und bessere Daten lenken Mittel gezielter. Ohne zusätzliches Geld bleibt der Abbau des Sanierungsstaus aber begrenzt; Wirkung kaum untersucht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=83', 'https://kommunal.de/sportstaetten-sanierung-kommunen-finanzen', 'offen', '2026-10-11', false, true, 'blind'),
  (9382, 37, 11, 'MV', 'Förderprogramm „Ehrenamt im Sport“ einführen und Weiterbildung der Ehrenamtlichen finanziell absichern', '{3703}', 9358, 2, 2, null, 'Kosten für Trainer und Übungsleiter treiben laut Panelstudie die Beiträge; Zuschüsse entlasten Vereine direkt. Umfang meist unbestimmt, Finanzierung aus dem Landeshaushalt nötig.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=99', 'https://www.bisp-surf.de/Record/PU202008006689', 'belegt', '2026-10-11', false, true, 'blind'),
  (9383, 37, 11, 'MV', 'Landesprogramm zur Zusammenarbeit von Schulen und Sportvereinen, um Vereine in den Ganztag einzubinden', '{3703}', 9362, 1, 3, null, 'Kann Vereinen Nachwuchs und bezahlte Ganztagsstunden bringen; belastet aber zugleich Ehrenamtliche, und die Wirkung auf die Vereinssituation ist kaum untersucht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=84', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9384, 37, 11, 'MV', 'Novellierung des Sportfördergesetzes: Bürokratie abbauen, Antragsverfahren digitalisieren, Förderung des Landessportbundes dynamisieren', '{3703}', 9356, 2, 2, null, 'Mehr und breitere Einnahmen gehen laut Panelstudie mit niedrigeren Beiträgen einher und verbessern die Finanzlage der Vereine. Dauerhafte Mehrausgaben belasten den Landeshaushalt.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=83', 'https://www.bisp-surf.de/Record/PU202008006689', 'belegt', '2026-10-11', false, true, 'blind'),
  (9385, 37, 11, 'ST', 'Sportstättenförderung für Kommunen und Vereine fortsetzen.', '{3701}', 9349, 1, 3, null, 'Sichert die bisherige Förderung ab und ist leicht umsetzbar; zusätzliche Mittel gegen den wachsenden Rückstand sind damit nicht verbunden.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=71', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9386, 37, 11, 'ST', 'Sportentwicklungsplanung und interkommunale Zusammenarbeit im Sport strukturell fördern.', '{3701}', 9350, 1, 3, null, 'Kommunen wünschen weniger Bürokratie in Förderprogrammen, und bessere Daten lenken Mittel gezielter. Ohne zusätzliches Geld bleibt der Abbau des Sanierungsstaus aber begrenzt; Wirkung kaum untersucht.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=71', 'https://kommunal.de/sportstaetten-sanierung-kommunen-finanzen', 'offen', '2026-10-11', false, true, 'blind'),
  (9387, 37, 11, 'ST', 'Neues Förderprogramm zur Entlastung der Vereine, damit ausreichend Trainerinnen, Trainer und Übungsleiter zur Verfügung stehen.', '{3703}', 9358, 2, 2, null, 'Kosten für Trainer und Übungsleiter treiben laut Panelstudie die Beiträge; Zuschüsse entlasten Vereine direkt. Umfang meist unbestimmt, Finanzierung aus dem Landeshaushalt nötig.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=71', 'https://www.bisp-surf.de/Record/PU202008006689', 'belegt', '2026-10-11', false, true, 'blind'),
  (9388, 37, 11, 'ST', 'Übungsleiter- und Ehrenamtspauschale auf Bundesebene anheben.', '{3703}', 9359, 1, 1, null, 'Kann Ehrenamt etwas attraktiver machen, eine Wirkung auf das Engagement ist aber nicht belegt; die Pauschalen wurden 2026 bereits erhöht. Regelt nur der Bund, das Land kann sich nur einsetzen.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=71', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9389, 37, 11, 'ST', 'Ehrenamts-Check bei allen neuen Gesetzen einführen und Vereinfachungen im Vereins- und Gemeinnützigkeitsrecht anstreben.', '{3703}', 9361, 1, 3, null, 'Bürokratie ist eine der größten Belastungen für Vereinsvorstände; Vereinfachung entlastet Ehrenamtliche. Viele Pflichten sind Bundes- oder EU-Recht, und die Wirkung auf die Vereinsfinanzen ist kaum untersucht.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=70', null, 'offen', '2026-10-11', false, true, 'blind'),
