  (9391, 37, 12, null, 'Länder, Kommunen und Vereine bei der Sanierung von Sportstätten unterstützen.', '{3701}', 9363, 2, 3, null, 'Setzt am Sanierungsstau an, und Sportstätten stützen die Vereinsteilnahme nachweislich. Der Bund finanziert solche Programme bereits; die Summen decken aber nur einen Teil des Rückstands.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=52', 'https://www.bisp-surf.de/Record/PU201407006674', 'belegt', '2026-10-11', false, true, 'blind'),
  (9392, 37, 12, null, 'Attraktivität und Zugänglichkeit des Ehrenamts im Breitensport erhöhen.', '{3703}', 9366, 1, 2, null, 'Zielt auf das Ehrenamt als Rückgrat der Vereine; konkrete Instrumente fehlen, und der Bund hat im Vereinssport nur begrenzte Hebel.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=52', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9393, 37, 12, 'BE', 'Vereinsinvestitionsprogramm für Sportstätten entbürokratisieren und finanziell stärken; Neubau, Sanierung und Barrierefreiheit fortsetzen', '{3701}', 9348, 2, 2, null, 'Setzt direkt am Sanierungsstau an; Studien zeigen, dass Sportplätze und Bäder die Vereinsteilnahme stützen. Landesmittel sind aber klein gegenüber dem Rückstand in Milliardenhöhe und hängen vom Haushalt ab.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=56', 'https://www.bisp-surf.de/Record/PU201407006674', 'belegt', '2026-10-11', false, true, 'blind'),
  (9394, 37, 12, 'BE', 'Landeseigene Schwimmbäder mit Typenschwimmhallen neu bauen und Bestandsbäder klimagerecht sanieren', '{3701}', 9348, 2, 2, null, 'Setzt direkt am Sanierungsstau an; Studien zeigen, dass Sportplätze und Bäder die Vereinsteilnahme stützen. Landesmittel sind aber klein gegenüber dem Rückstand in Milliardenhöhe und hängen vom Haushalt ab.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=56', 'https://www.bisp-surf.de/Record/PU201407006674', 'belegt', '2026-10-11', false, true, 'blind'),
  (9395, 37, 12, 'BE', 'Zentrale Planungs- und Baueinheit für bezirkliche Sportinfrastruktur einrichten, die Bau und Sanierung beschleunigt', '{3701}', 9350, 1, 3, null, 'Kommunen wünschen weniger Bürokratie in Förderprogrammen, und bessere Daten lenken Mittel gezielter. Ohne zusätzliches Geld bleibt der Abbau des Sanierungsstaus aber begrenzt; Wirkung kaum untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=56', 'https://kommunal.de/sportstaetten-sanierung-kommunen-finanzen', 'offen', '2026-10-11', false, true, 'blind'),
  (9396, 37, 12, 'BE', 'Sportstätten für Vereine weiterhin gebührenfrei zur Verfügung stellen', '{3702}', 9354, 1, 3, null, 'Verhindert Beitragserhöhungen durch neue Nutzungsgebühren, die laut Studien auf Beiträge durchschlagen; bringt gegenüber heute aber keine zusätzliche Entlastung.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=55', 'https://www.bisp-surf.de/Record/PU202008006689', 'belegt', '2026-10-11', false, true, 'blind'),
  (9397, 37, 12, 'BE', 'Fördervereinbarung mit dem Landessportbund nach 2029 fortführen', '{3703}', 9357, 1, 3, null, 'Gibt Vereinen Planungssicherheit und ist leicht umsetzbar; zusätzliche Mittel gegen gestiegene Kosten sind damit nicht verbunden.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=56', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9398, 37, 12, 'BE', 'Trainer*innen weiter qualifizieren und ihre Einkommenssituation verbessern (Grenzfall: Zuordnung zur Vereinsfinanzierung offen)', '{3703}', 9358, 2, 2, null, 'Kosten für Trainer und Übungsleiter treiben laut Panelstudie die Beiträge; Zuschüsse entlasten Vereine direkt. Umfang meist unbestimmt, Finanzierung aus dem Landeshaushalt nötig.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=56', 'https://www.bisp-surf.de/Record/PU202008006689', 'belegt', '2026-10-11', false, true, 'blind'),
  (9399, 37, 12, 'BE', 'Ehrenamtliche Strukturen weiter entbürokratisieren (Grenzfall: allgemeines Ehrenamt, kein Sportbezug)', '{3703}', 9360, 1, 3, null, 'Würdigt Ehrenamt und erleichtert Engagement; Evaluationen zeigen Zufriedenheit der Karteninhaber, aber keinen Nachweis für mehr Engagement. Die Finanzlage der Vereine ändert sich kaum.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=50', 'https://www.baden-wuerttemberg.de/de/service/presse/pressemitteilung/pid/erprobung-der-ehrenamtskarte-laeuft-erfolgreich', 'offen', '2026-10-11', false, true, 'blind'),
  (9400, 37, 12, 'MV', 'Sportstätten mit Sanierungsbedarf über bestehende Programme fördern', '{3701}', 9349, 1, 3, null, 'Sichert die bisherige Förderung ab und ist leicht umsetzbar; zusätzliche Mittel gegen den wachsenden Rückstand sind damit nicht verbunden.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=40', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9401, 37, 12, 'MV', 'Vereinen, Karneval und Kapellen für bis zu drei Veranstaltungen im Jahr die GEMA-Gebühren erstatten', '{3703}', null, 1, 3, null, 'Erstattung von GEMA-Gebühren entlastet Vereine bei Veranstaltungen gezielt; der Betrag ist gering und betrifft Training und Sportstätten nicht.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=5', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9402, 37, 12, 'MV', 'Projekte wie „Sport in Schule und Verein“ fortführen und die Zusammenarbeit der Fachverbände verstärken', '{3703}', 9362, 1, 3, null, 'Kann Vereinen Nachwuchs und bezahlte Ganztagsstunden bringen; belastet aber zugleich Ehrenamtliche, und die Wirkung auf die Vereinssituation ist kaum untersucht.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=41', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9403, 37, 12, 'ST', 'Sportstätten erhalten und modernisieren; Kommunen bei Investitionen in Neubau und Modernisierung unterstützen', '{3701}', 9348, 2, 2, null, 'Setzt direkt am Sanierungsstau an; Studien zeigen, dass Sportplätze und Bäder die Vereinsteilnahme stützen. Landesmittel sind aber klein gegenüber dem Rückstand in Milliardenhöhe und hängen vom Haushalt ab.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=40', 'https://www.bisp-surf.de/Record/PU201407006674', 'belegt', '2026-10-11', false, true, 'blind'),
  (9404, 37, 12, 'ST', 'Vereinspauschalen verdoppeln, dynamisieren und im Sportfördergesetz festschreiben', '{3703}', 9356, 2, 2, null, 'Mehr und breitere Einnahmen gehen laut Panelstudie mit niedrigeren Beiträgen einher und verbessern die Finanzlage der Vereine. Dauerhafte Mehrausgaben belasten den Landeshaushalt.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=40', 'https://www.bisp-surf.de/Record/PU202008006689', 'belegt', '2026-10-11', false, true, 'blind'),
  (9405, 37, 12, 'ST', 'Vereine bei der Digitalisierung ihrer Arbeit unterstützen', '{3703}', 9361, 1, 3, null, 'Bürokratie ist eine der größten Belastungen für Vereinsvorstände; Vereinfachung entlastet Ehrenamtliche. Viele Pflichten sind Bundes- oder EU-Recht, und die Wirkung auf die Vereinsfinanzen ist kaum untersucht.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=40', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9406, 37, 12, 'ST', 'Ehrenamtsgesetz im Sport anstreben', '{3703}', 9360, 1, 3, null, 'Würdigt Ehrenamt und erleichtert Engagement; Evaluationen zeigen Zufriedenheit der Karteninhaber, aber keinen Nachweis für mehr Engagement. Die Finanzlage der Vereine ändert sich kaum.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=40', 'https://www.baden-wuerttemberg.de/de/service/presse/pressemitteilung/pid/erprobung-der-ehrenamtskarte-laeuft-erfolgreich', 'offen', '2026-10-11', false, true, 'blind'),
  (9407, 37, 13, null, 'Bundesprogramm zur Sanierung von Sportstätten und Schwimmbädern ausbauen', '{3701}', 9363, 2, 3, null, 'Setzt am Sanierungsstau an, und Sportstätten stützen die Vereinsteilnahme nachweislich. Der Bund finanziert solche Programme bereits; die Summen decken aber nur einen Teil des Rückstands.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=112', 'https://www.bisp-surf.de/Record/PU201407006674', 'belegt', '2026-10-11', false, true, 'blind'),
  (9408, 37, 13, null, 'Vorhandene Sportstätten bei einer Sportgroßveranstaltung einbeziehen, neue für die Öffentlichkeit nutzbar machen', '{3701}', null, 1, 1, null, 'Nachnutzung von Wettkampfstätten kann Breitensport nützen; Studien zu Großereignissen zeigen gemischte Erfahrungen. Hängt von einer Vergabe durch Dritte ab.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=112', 'https://www.gov.scot/publications/updated-review-evidence-legacy-major-sporting-events-july-2015/pages/6/', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9409, 37, 13, null, 'Auskömmlichere Kommunalfinanzierung und Deutschlandfonds, damit Kommunen Investitionen etwa in Sportplätze und Schwimmbäder finanzieren können', '{3701}', null, 2, 2, null, 'Bessere Kommunalfinanzen und ein Investitionsfonds setzen an der Finanzierung des Sanierungsstaus an; Mittel sind nicht zweckgebunden für Sport, Umfang und Finanzierung offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=108', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9410, 37, 13, null, 'Zivilgesellschaftliche Organisationen von überflüssiger Bürokratie entlasten', '{3703}', 9365, 1, 2, null, 'Entlastet Vorstände bei häufig genannten Belastungen; Datenschutz ist zum Teil EU-Recht, und die Wirkung auf Vereinsfinanzen und Sportstätten ist kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=112', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9411, 37, 13, 'BE', 'Netz barrierefreier, klimaneutraler Sportstätten schaffen, mit mindestens drei inklusiven Sportstätten pro Bezirk', '{3701}', 9348, 2, 2, null, 'Setzt direkt am Sanierungsstau an; Studien zeigen, dass Sportplätze und Bäder die Vereinsteilnahme stützen. Landesmittel sind aber klein gegenüber dem Rückstand in Milliardenhöhe und hängen vom Haushalt ab.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=39', 'https://www.bisp-surf.de/Record/PU201407006674', 'belegt', '2026-10-11', false, true, 'blind'),
  (9412, 37, 13, 'BE', 'Förderbedingungen für hauptamtliche Verwaltungskräfte in Vereinen so ändern, dass die Mitgliederzahlen deutlich sinken', '{3703}', 9358, 2, 2, null, 'Kosten für Trainer und Übungsleiter treiben laut Panelstudie die Beiträge; Zuschüsse entlasten Vereine direkt. Umfang meist unbestimmt, Finanzierung aus dem Landeshaushalt nötig.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=37', 'https://www.bisp-surf.de/Record/PU202008006689', 'belegt', '2026-10-11', false, true, 'blind'),
  (9413, 37, 13, 'BE', 'Berliner Bäder energetisch sanieren, um die Kosten zu senken', '{3702}', 9355, 2, 2, null, 'Messungen in Pilotbädern zeigen deutliche Einsparungen bei Wärme und Strom und senken so Betriebsverluste. Hohe Investitionen nötig; Wirkung erst nach Jahren.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=40', 'https://www.energiezukunft.eu/bauen/bauzukunft/energieeffizient-im-spa', 'belegt', '2026-10-11', false, true, 'blind'),
  (9414, 37, 13, 'MV', 'Flächendeckendes, niedrigschwelliges Angebot an Jugendclubs, Vereinen, Kultur- und Sportstätten unterstützen', '{3703}', null, 1, 2, null, 'Bekennt sich zu wohnortnahen Vereinsangeboten, nennt aber weder Mittel noch Instrument; Wirkung daher kaum abschätzbar.', 'https://gruene-mv.de/?wpdmdl=33772#page=64', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9415, 37, 13, 'MV', 'Bessere Möglichkeiten zur Freistellung schaffen, um ehrenamtliches Engagement zu erleichtern', '{3703}', 9360, 1, 3, null, 'Würdigt Ehrenamt und erleichtert Engagement; Evaluationen zeigen Zufriedenheit der Karteninhaber, aber keinen Nachweis für mehr Engagement. Die Finanzlage der Vereine ändert sich kaum.', 'https://gruene-mv.de/?wpdmdl=33772#page=68', 'https://www.baden-wuerttemberg.de/de/service/presse/pressemitteilung/pid/erprobung-der-ehrenamtskarte-laeuft-erfolgreich', 'offen', '2026-10-11', false, true, 'blind'),
  (9416, 37, 13, 'ST', 'Sanierung von Sportstätten und Schwimmbädern unterstützen, mit Fokus auf Nachhaltigkeit und Inklusion', '{3701}', 9348, 2, 2, null, 'Setzt direkt am Sanierungsstau an; Studien zeigen, dass Sportplätze und Bäder die Vereinsteilnahme stützen. Landesmittel sind aber klein gegenüber dem Rückstand in Milliardenhöhe und hängen vom Haushalt ab.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=72', 'https://www.bisp-surf.de/Record/PU201407006674', 'belegt', '2026-10-11', false, true, 'blind'),
  (9417, 37, 13, 'ST', 'Vereine gezielt bei Energiekosten unterstützen', '{3702}', null, 1, 3, null, 'Zuschüsse zu Energiekosten entlasten Vereine kurzfristig, wie Hilfsprogramme in der Energiekrise; ohne Sanierung bleiben die Kosten aber bestehen, eine Evaluation fehlt.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=72', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9418, 37, 13, 'ST', 'Ehrenamtspauschale im Sport erhöhen und die Anerkennung des Ehrenamts verbessern', '{3703}', 9359, 1, 1, null, 'Kann Ehrenamt etwas attraktiver machen, eine Wirkung auf das Engagement ist aber nicht belegt; die Pauschalen wurden 2026 bereits erhöht. Regelt nur der Bund, das Land kann sich nur einsetzen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=73', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9419, 37, 13, 'ST', 'Kooperationen zwischen Sportvereinen und Schulen ausbauen', '{3703}', 9362, 1, 3, null, 'Kann Vereinen Nachwuchs und bezahlte Ganztagsstunden bringen; belastet aber zugleich Ehrenamtliche, und die Wirkung auf die Vereinssituation ist kaum untersucht.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=73', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9420, 37, 13, 'ST', 'Bürokratische Hürden für ehrenamtliches Engagement abbauen', '{3703}', 9360, 1, 3, null, 'Würdigt Ehrenamt und erleichtert Engagement; Evaluationen zeigen Zufriedenheit der Karteninhaber, aber keinen Nachweis für mehr Engagement. Die Finanzlage der Vereine ändert sich kaum.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=74', 'https://www.baden-wuerttemberg.de/de/service/presse/pressemitteilung/pid/erprobung-der-ehrenamtskarte-laeuft-erfolgreich', 'offen', '2026-10-11', false, true, 'blind'),
  (9421, 37, 14, null, 'Vereine bei Haftungsrisiken und Bürokratie entlasten, Dokumentations- und Aufbewahrungspflichten reduzieren', '{3703}', 9365, 1, 2, null, 'Entlastet Vorstände bei häufig genannten Belastungen; Datenschutz ist zum Teil EU-Recht, und die Wirkung auf Vereinsfinanzen und Sportstätten ist kaum untersucht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=32', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9422, 37, 14, null, 'Übungsleiter- und Ehrenamtspauschalen sowie relevante Einnahmegrenzen anpassen', '{3703}', 9364, 1, 3, null, 'Vom Bund einfach umsetzbar und für Engagierte spürbar; eine Wirkung auf Zahl der Ehrenamtlichen oder Vereinsfinanzen ist nicht belegt, Vereine müssen die Zahlungen selbst aufbringen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=32', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9423, 37, 14, null, 'Engagement der Babyboomer-Generation gezielt einbinden, um Sportangebote und Vereinsarbeit zu beleben', '{3703}', 9366, 1, 2, null, 'Zielt auf das Ehrenamt als Rückgrat der Vereine; konkrete Instrumente fehlen, und der Bund hat im Vereinssport nur begrenzte Hebel.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=32', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9424, 37, 14, null, 'Zusammenarbeit zwischen Vereinen, Schulen, Unternehmen und sozialen Einrichtungen stärken', '{3703}', null, 1, 1, null, 'Mehr Zusammenarbeit kann Vereinen Mitglieder bringen; Schulen sind Ländersache, und Instrumente des Bundes fehlen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=32', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9425, 37, 14, 'BE', 'Bestehende Sportstätten für eine mögliche Olympia-Austragung in erster Linie modernisieren und renovieren; neue Anlagen nur bei dringendem sportlichem Bedarf', '{3701}', null, 1, 1, null, 'Modernisierung bestehender Anlagen statt Neubau ist nachhaltiger; ob Großereignisse dem Breitensport nützen, ist in Studien gemischt. Hängt von einer Vergabe durch Dritte ab.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=83', 'https://www.gov.scot/publications/updated-review-evidence-legacy-major-sporting-events-july-2015/pages/6/', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9426, 37, 14, 'BE', 'Instandhaltung von Sportstätten auf eine neue Grundlage stellen, damit Nutzende Baumaßnahmen eigenverantwortlich mit finanzieller Planungssicherheit umsetzen können', '{3701}', null, 1, 2, null, 'Eigenverantwortliche Instandhaltung mit Planungssicherheit kann Sanierungen beschleunigen; Mittel und Ausgestaltung bleiben offen, Vereine tragen mehr Verantwortung.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=83', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9427, 37, 14, 'BE', 'Landessportbund bei der Erhaltung der Vielfalt des Sports unterstützen und seine Finanzierung langfristig garantieren', '{3703}', 9357, 1, 3, null, 'Gibt Vereinen Planungssicherheit und ist leicht umsetzbar; zusätzliche Mittel gegen gestiegene Kosten sind damit nicht verbunden.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=84', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9428, 37, 14, 'MV', 'Langfristiges Sanierungsprogramm für Sportstätten gemeinsam mit den Kommunen, mit verlässlicher und planbarer Förderkulisse', '{3701}', 9348, 2, 2, null, 'Setzt direkt am Sanierungsstau an; Studien zeigen, dass Sportplätze und Bäder die Vereinsteilnahme stützen. Landesmittel sind aber klein gegenüber dem Rückstand in Milliardenhöhe und hängen vom Haushalt ab.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=124', 'https://www.bisp-surf.de/Record/PU201407006674', 'belegt', '2026-10-11', false, true, 'blind'),
  (9429, 37, 14, 'MV', 'Einen regelmäßig fortzuschreibenden Zustandsbericht der Sportstätten im Land für den Mitteleinsatz einfordern', '{3701}', 9350, 1, 3, null, 'Kommunen wünschen weniger Bürokratie in Förderprogrammen, und bessere Daten lenken Mittel gezielter. Ohne zusätzliches Geld bleibt der Abbau des Sanierungsstaus aber begrenzt; Wirkung kaum untersucht.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=124', 'https://kommunal.de/sportstaetten-sanierung-kommunen-finanzen', 'offen', '2026-10-11', false, true, 'blind'),
  (9430, 37, 14, 'MV', 'Bürokratische Hürden für Förderanträge, Genehmigungen und Bauvorhaben im Sport abbauen', '{3701}', 9350, 1, 3, null, 'Kommunen wünschen weniger Bürokratie in Förderprogrammen, und bessere Daten lenken Mittel gezielter. Ohne zusätzliches Geld bleibt der Abbau des Sanierungsstaus aber begrenzt; Wirkung kaum untersucht.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=124', 'https://kommunal.de/sportstaetten-sanierung-kommunen-finanzen', 'offen', '2026-10-11', false, true, 'blind'),
  (9431, 37, 14, 'MV', 'Vereine sollen Sporthallen und kommunale Einrichtungen außerhalb der Nutzungszeiten unbürokratisch und möglichst kostenfrei nutzen können', '{3702}', 9353, 2, 2, null, 'Sportstättenkosten bestimmen laut Panelstudie die Höhe der Vereinsbeiträge, daher entlastet freie Nutzung spürbar. Die Kosten tragen aber Kommunen, deren Sportbetriebe oft schon Verluste haben; Ausgleich durch das Land nötig.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=122', 'https://www.bisp-surf.de/Record/PU202008006689', 'belegt', '2026-10-11', false, true, 'blind'),
  (9432, 37, 14, 'MV', 'Landesförderprogramme für Vereine stärker pauschalisieren und Antrags- und Verwendungsnachweise vereinfachen', '{3703}', 9361, 1, 3, null, 'Bürokratie ist eine der größten Belastungen für Vereinsvorstände; Vereinfachung entlastet Ehrenamtliche. Viele Pflichten sind Bundes- oder EU-Recht, und die Wirkung auf die Vereinsfinanzen ist kaum untersucht.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=122', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9433, 37, 14, 'MV', 'Steuerliche Freibeträge für Übungsleiter- und Ehrenamtspauschalen erhöhen', '{3703}', 9359, 1, 1, null, 'Kann Ehrenamt etwas attraktiver machen, eine Wirkung auf das Engagement ist aber nicht belegt; die Pauschalen wurden 2026 bereits erhöht. Regelt nur der Bund, das Land kann sich nur einsetzen.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=122', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9434, 37, 14, 'MV', 'Landesgesetze und Verwaltungsvorschriften auf unnötige Belastungen für Vereine überprüfen und vereinfachen', '{3703}', 9361, 1, 3, null, 'Bürokratie ist eine der größten Belastungen für Vereinsvorstände; Vereinfachung entlastet Ehrenamtliche. Viele Pflichten sind Bundes- oder EU-Recht, und die Wirkung auf die Vereinsfinanzen ist kaum untersucht.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=122', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9435, 37, 14, 'MV', 'Haftungsbeschränkungen für ehrenamtliche Vereinsvorstände anregen', '{3703}', null, 1, 1, null, 'Kann die Angst vor Vorstandsämtern mindern; eine Haftungsbegrenzung für Ehrenamtliche besteht im Bundesrecht bereits, das Land kann sie nur anregen.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=122', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9436, 37, 14, 'MV', 'Ehrenamtskarte durch private Akzeptanzstellen attraktiver machen und Nachweise bürokratieärmer anerkennen', '{3703}', 9360, 1, 3, null, 'Würdigt Ehrenamt und erleichtert Engagement; Evaluationen zeigen Zufriedenheit der Karteninhaber, aber keinen Nachweis für mehr Engagement. Die Finanzlage der Vereine ändert sich kaum.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=122', 'https://www.baden-wuerttemberg.de/de/service/presse/pressemitteilung/pid/erprobung-der-ehrenamtskarte-laeuft-erfolgreich', 'offen', '2026-10-11', false, true, 'blind'),
  (9437, 37, 14, 'MV', 'Ehrenamtliche rechtlich verlässlich gegen physische und verbale Angriffe schützen', '{3703}', null, 1, 1, null, 'Schutz vor Angriffen kann Schiedsrichter und Übungsleiter halten; das Strafrecht ist Bundesrecht, und ein Effekt auf die Vereinslage ist kaum untersucht.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=122', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9438, 37, 14, 'MV', 'Verlässliche und unbürokratische Erstattung für Arbeitgeber sichern, wenn Beschäftigte für Ehrenamt freigestellt werden', '{3703}', 9360, 1, 3, null, 'Würdigt Ehrenamt und erleichtert Engagement; Evaluationen zeigen Zufriedenheit der Karteninhaber, aber keinen Nachweis für mehr Engagement. Die Finanzlage der Vereine ändert sich kaum.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=122', 'https://www.baden-wuerttemberg.de/de/service/presse/pressemitteilung/pid/erprobung-der-ehrenamtskarte-laeuft-erfolgreich', 'offen', '2026-10-11', false, true, 'blind'),
  (9439, 37, 14, 'MV', 'Anreize schaffen, damit auch ältere Menschen und Menschen mit Behinderungen sich ehrenamtlich engagieren', '{3703}', 9360, 1, 3, null, 'Würdigt Ehrenamt und erleichtert Engagement; Evaluationen zeigen Zufriedenheit der Karteninhaber, aber keinen Nachweis für mehr Engagement. Die Finanzlage der Vereine ändert sich kaum.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=122', 'https://www.baden-wuerttemberg.de/de/service/presse/pressemitteilung/pid/erprobung-der-ehrenamtskarte-laeuft-erfolgreich', 'offen', '2026-10-11', false, true, 'blind'),
  (9440, 37, 14, 'ST', 'Kontinuierliche Investitionen in Sportstätten', '{3701}', 9348, 2, 2, null, 'Setzt direkt am Sanierungsstau an; Studien zeigen, dass Sportplätze und Bäder die Vereinsteilnahme stützen. Landesmittel sind aber klein gegenüber dem Rückstand in Milliardenhöhe und hängen vom Haushalt ab.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=52', 'https://www.bisp-surf.de/Record/PU201407006674', 'belegt', '2026-10-11', false, true, 'blind'),
  (9441, 37, 14, 'ST', 'Planungs- und Förderverfahren für Sportstätten beschleunigen, digitalisieren und ehrenamtsfreundlich gestalten', '{3701}', 9350, 1, 3, null, 'Kommunen wünschen weniger Bürokratie in Förderprogrammen, und bessere Daten lenken Mittel gezielter. Ohne zusätzliches Geld bleibt der Abbau des Sanierungsstaus aber begrenzt; Wirkung kaum untersucht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=52', 'https://kommunal.de/sportstaetten-sanierung-kommunen-finanzen', 'offen', '2026-10-11', false, true, 'blind'),
  (9442, 37, 14, 'ST', 'Vereine mit eigenen Liegenschaften und Vereine mit kommunalen Sportstätten gleichstellen; Sportfördergesetz anpassen', '{3702}', null, 2, 2, null, 'Vereine mit eigenen Anlagen tragen Betriebskosten selbst, die laut Studien die Beiträge erhöhen; Gleichstellung entlastet sie. Erfordert Gesetzesänderung und dauerhafte Mittel.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=52', 'https://www.bisp-surf.de/Record/PU202008006689', 'belegt', '2026-10-11', false, true, 'blind'),
  (9443, 37, 14, 'ST', 'Pauschalförderung für Vereine und Mitgliedsorganisationen erhöhen und dynamisieren', '{3703}', 9356, 2, 2, null, 'Mehr und breitere Einnahmen gehen laut Panelstudie mit niedrigeren Beiträgen einher und verbessern die Finanzlage der Vereine. Dauerhafte Mehrausgaben belasten den Landeshaushalt.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=52', 'https://www.bisp-surf.de/Record/PU202008006689', 'belegt', '2026-10-11', false, true, 'blind'),
  (9444, 37, 14, 'ST', 'Förderungen für ehrenamtliches Engagement bürokratisch entlasten und vereinfachen', '{3703}', 9361, 1, 3, null, 'Bürokratie ist eine der größten Belastungen für Vereinsvorstände; Vereinfachung entlastet Ehrenamtliche. Viele Pflichten sind Bundes- oder EU-Recht, und die Wirkung auf die Vereinsfinanzen ist kaum untersucht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=51', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9445, 37, 14, 'ST', 'Ehrenamtliches Engagement im Sport durch Anerkennung, Sichtbarkeit und bessere Rahmenbedingungen stärken', '{3703}', 9360, 1, 3, null, 'Würdigt Ehrenamt und erleichtert Engagement; Evaluationen zeigen Zufriedenheit der Karteninhaber, aber keinen Nachweis für mehr Engagement. Die Finanzlage der Vereine ändert sich kaum.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=52', 'https://www.baden-wuerttemberg.de/de/service/presse/pressemitteilung/pid/erprobung-der-ehrenamtskarte-laeuft-erfolgreich', 'offen', '2026-10-11', false, true, 'blind'),
  (9446, 37, 14, 'ST', 'Qualifizierte Trainer- und Übungsleiterstrukturen dauerhaft sichern', '{3703}', 9358, 2, 2, null, 'Kosten für Trainer und Übungsleiter treiben laut Panelstudie die Beiträge; Zuschüsse entlasten Vereine direkt. Umfang meist unbestimmt, Finanzierung aus dem Landeshaushalt nötig.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=52', 'https://www.bisp-surf.de/Record/PU202008006689', 'belegt', '2026-10-11', false, true, 'blind'),
  (9447, 37, 14, 'ST', 'Kooperationen mit Sportvereinen ausbauen und Sport in Kita und Schule stärken', '{3703}', 9362, 1, 3, null, 'Kann Vereinen Nachwuchs und bezahlte Ganztagsstunden bringen; belastet aber zugleich Ehrenamtliche, und die Wirkung auf die Vereinssituation ist kaum untersucht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=52', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9448, 37, 15, 'BE', 'Sanierungsstau bei Sportflächen durch massive Investitionen und ein Sofortprogramm beheben.', '{3701}', 9348, 2, 2, null, 'Setzt direkt am Sanierungsstau an; Studien zeigen, dass Sportplätze und Bäder die Vereinsteilnahme stützen. Landesmittel sind aber klein gegenüber dem Rückstand in Milliardenhöhe und hängen vom Haushalt ab.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=65', 'https://www.bisp-surf.de/Record/PU201407006674', 'belegt', '2026-10-11', false, true, 'blind'),
  (9449, 37, 15, 'BE', 'Bei Neubauvorhaben den Bedarf an zusätzlichen Sportflächen berücksichtigen.', '{3701}', 9352, 1, 2, null, 'Schafft zusätzliche, meist offene Sportflächen bei Neubauten; der Rückstand bei bestehenden Hallen und Bädern bleibt unberührt. Verpflichtungen für Investoren brauchen Bauplanungsrecht und Verträge.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=66', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9450, 37, 15, 'BE', 'Begrenzung der Dauerförderung von Trägern und Vereinen, ergänzt um regelmäßige Wirksamkeitsprüfung.', '{3703}', null, 0, 3, null, 'Wirksamkeitsprüfungen können Mittel besser lenken; eine Begrenzung der Dauerförderung nimmt Vereinen aber Planungssicherheit und verbessert ihre Finanzlage nicht.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=49', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9451, 37, 15, 'MV', 'Kommunen und Vereine sollen Mittel für Sanierung von Vereins- und Schulsportstätten sowie Schwimmhallen vollständig und unbürokratisch abrufen können', '{3701}', 9350, 1, 3, null, 'Kommunen wünschen weniger Bürokratie in Förderprogrammen, und bessere Daten lenken Mittel gezielter. Ohne zusätzliches Geld bleibt der Abbau des Sanierungsstaus aber begrenzt; Wirkung kaum untersucht.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=72', 'https://kommunal.de/sportstaetten-sanierung-kommunen-finanzen', 'offen', '2026-10-11', false, true, 'blind'),
  (9452, 37, 15, 'MV', 'Aufwandsentschädigungen für ehrenamtliche Übungsleitende, Trainer und Schiedsrichter regelmäßig an Lohn- und Preisentwicklung anpassen', '{3703}', 9359, 1, 1, null, 'Kann Ehrenamt etwas attraktiver machen, eine Wirkung auf das Engagement ist aber nicht belegt; die Pauschalen wurden 2026 bereits erhöht. Regelt nur der Bund, das Land kann sich nur einsetzen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=66', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9453, 37, 15, 'MV', 'Bürokratische Hürden für Vereine (Förderanträge, Versicherungs- und Nachweispflichten) systematisch abbauen', '{3703}', 9361, 1, 3, null, 'Bürokratie ist eine der größten Belastungen für Vereinsvorstände; Vereinfachung entlastet Ehrenamtliche. Viele Pflichten sind Bundes- oder EU-Recht, und die Wirkung auf die Vereinsfinanzen ist kaum untersucht.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=66', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9454, 37, 15, 'ST', 'Landesprogramm: kostenfreie Vereinsteilnahme am Sport für alle Kinder bis 18', '{3703}', null, 2, 1, null, 'Senkt Beiträge direkt und bringt Vereinen Einnahmen; Erfahrungen mit Sportgutscheinen zeigen hohe Reichweite, aber viele Nutzer waren schon aktiv. Sehr teuer, Finanzierung ungeklärt.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=19', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC7460334', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9455, 37, 15, 'ST', 'Vereinsförderung nur mit Bekenntnis zur demokratischen Ordnung und patriotischen Grundhaltung', '{3703}', null, 0, 1, null, 'Knüpft Förderung an eine Gesinnungserklärung, bringt Vereinen kein zusätzliches Geld und erhöht den Aufwand; eine Pflicht zu einer bestimmten Grundhaltung ist verfassungsrechtlich heikel.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=135', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9456, 37, 15, 'ST', 'Ehrenamtskarte einführen und ehrenamtliches Engagement im Bevölkerungsschutz anerkennen', '{3703}', 9360, 1, 3, null, 'Würdigt Ehrenamt und erleichtert Engagement; Evaluationen zeigen Zufriedenheit der Karteninhaber, aber keinen Nachweis für mehr Engagement. Die Finanzlage der Vereine ändert sich kaum.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=113', 'https://www.baden-wuerttemberg.de/de/service/presse/pressemitteilung/pid/erprobung-der-ehrenamtskarte-laeuft-erfolgreich', 'offen', '2026-10-11', false, true, 'blind'),
  (9457, 37, 16, null, 'Der Bund beteiligt sich 15 Jahre lang mit jeweils einer Milliarde Euro pro Jahr an Sanierung und Neubau von Turnhallen, Sportplätzen und Schwimmbädern.', '{3701}', null, 3, 2, null, 'Eine Milliarde jährlich über 15 Jahre setzt direkt am Sanierungsstau an; Sportstätten stützen die Vereinsteilnahme nachweislich. Finanzierung über so lange Zeit ist im Haushalt nicht gesichert.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=56', 'https://www.bisp-surf.de/Record/PU201407006674', 'belegt', '2026-10-11', false, true, 'blind'),
  (9458, 37, 16, null, 'Einrichtungen für Kinder und Jugendliche, darunter Sportvereine und Schwimmbäder, sollen gebührenfrei sein; Finanzierung der Kommunen verbessern.', '{3702,3703}', null, 2, 1, null, 'Gebührenfreiheit für Kinder in Vereinen und Bädern senkt Kosten direkt; Erfahrungen mit Teilhabeleistungen zeigen aber geringe Nutzung. Finanzierung bei Kommunen und Ländern ungeklärt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=16', 'https://www.der-paritaetische.de/alle-meldungen/paritaetische-expertise-zeigt-nicht-einmal-jedes-fuenfte-kind-im-buergergeldbezug-profitiert-von-teilhabeleistungen/', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9459, 37, 16, 'BE', 'Ein „Jahrzehnt der Investitionen“ in den Breitensport mit zentraler Baudienststelle für den Sportstättenbau', '{3701}', 9348, 2, 2, null, 'Setzt direkt am Sanierungsstau an; Studien zeigen, dass Sportplätze und Bäder die Vereinsteilnahme stützen. Landesmittel sind aber klein gegenüber dem Rückstand in Milliardenhöhe und hängen vom Haushalt ab.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=316', 'https://www.bisp-surf.de/Record/PU201407006674', 'belegt', '2026-10-11', false, true, 'blind'),
  (9460, 37, 16, 'BE', 'Reaktivierung ungenutzter Sportorte in die Eigenverantwortung der Vereine geben, saisonale Sportstätten ganzjährig nutzen', '{3702}', null, 1, 2, null, 'Übertragung ungenutzter Anlagen an Vereine kann kommunale Betriebskosten senken und Flächen zurückgewinnen; belastet aber Vereine mit Betrieb und Unterhalt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=317', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9461, 37, 16, 'BE', 'Nutzung der Bäder für Vereine bleibt unentgeltlich', '{3702}', 9354, 1, 3, null, 'Verhindert Beitragserhöhungen durch neue Nutzungsgebühren, die laut Studien auf Beiträge durchschlagen; bringt gegenüber heute aber keine zusätzliche Entlastung.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=318', 'https://www.bisp-surf.de/Record/PU202008006689', 'belegt', '2026-10-11', false, true, 'blind'),
  (9462, 37, 16, 'BE', 'Energetische Sanierung der Kälteanlagen von Eissporthallen per Investitionsprogramm', '{3702}', 9355, 2, 2, null, 'Messungen in Pilotbädern zeigen deutliche Einsparungen bei Wärme und Strom und senken so Betriebsverluste. Hohe Investitionen nötig; Wirkung erst nach Jahren.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=320', 'https://www.energiezukunft.eu/bauen/bauzukunft/energieeffizient-im-spa', 'belegt', '2026-10-11', false, true, 'blind'),
  (9463, 37, 16, 'BE', 'Ein ergänzender Fonds mit dem Landessportbund für Personal und Instandhaltung in den Vereinen', '{3703}', 9358, 2, 2, null, 'Kosten für Trainer und Übungsleiter treiben laut Panelstudie die Beiträge; Zuschüsse entlasten Vereine direkt. Umfang meist unbestimmt, Finanzierung aus dem Landeshaushalt nötig.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=313', 'https://www.bisp-surf.de/Record/PU202008006689', 'belegt', '2026-10-11', false, true, 'blind'),
  (9464, 37, 16, 'BE', 'Ehrenamt durch Digitalisierung von Bürokratie entlasten, Übungsleiterpauschale anheben', '{3703}', 9359, 1, 1, null, 'Kann Ehrenamt etwas attraktiver machen, eine Wirkung auf das Engagement ist aber nicht belegt; die Pauschalen wurden 2026 bereits erhöht. Regelt nur der Bund, das Land kann sich nur einsetzen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=313', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9465, 37, 16, 'BE', 'Schulschwimmzentren und kostenlose Nachschulungsangebote in Kooperation mit Vereinen ausbauen', '{3703}', 9362, 1, 3, null, 'Kann Vereinen Nachwuchs und bezahlte Ganztagsstunden bringen; belastet aber zugleich Ehrenamtliche, und die Wirkung auf die Vereinssituation ist kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=318', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9466, 37, 16, 'BE', 'Sportflächen bei großen Wohnungsneubauvorhaben verbindlich festschreiben', '{3701}', 9352, 1, 2, null, 'Schafft zusätzliche, meist offene Sportflächen bei Neubauten; der Rückstand bei bestehenden Hallen und Bädern bleibt unberührt. Verpflichtungen für Investoren brauchen Bauplanungsrecht und Verträge.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=322', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9467, 37, 16, 'MV', 'Sportanlagen ausbauen und sanieren', '{3701}', 9348, 2, 2, null, 'Setzt direkt am Sanierungsstau an; Studien zeigen, dass Sportplätze und Bäder die Vereinsteilnahme stützen. Landesmittel sind aber klein gegenüber dem Rückstand in Milliardenhöhe und hängen vom Haushalt ab.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=11', 'https://www.bisp-surf.de/Record/PU201407006674', 'belegt', '2026-10-11', false, true, 'blind'),
  (9468, 37, 16, 'MV', 'Ausfinanzierung von Sportförderprogrammen, darunter ein Programm für Sport in Schule und Verein', '{3703}', 9362, 1, 3, null, 'Kann Vereinen Nachwuchs und bezahlte Ganztagsstunden bringen; belastet aber zugleich Ehrenamtliche, und die Wirkung auf die Vereinssituation ist kaum untersucht.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=11', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9469, 37, 16, 'MV', 'Anerkennung des Ehrenamts stärken durch Weiterbildung und Freistellungsregelungen für Ehrenamtliche', '{3703}', 9360, 1, 3, null, 'Würdigt Ehrenamt und erleichtert Engagement; Evaluationen zeigen Zufriedenheit der Karteninhaber, aber keinen Nachweis für mehr Engagement. Die Finanzlage der Vereine ändert sich kaum.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=13', 'https://www.baden-wuerttemberg.de/de/service/presse/pressemitteilung/pid/erprobung-der-ehrenamtskarte-laeuft-erfolgreich', 'offen', '2026-10-11', false, true, 'blind'),
  (9470, 37, 16, 'ST', 'Investitionsprogramme für die Sanierung von Bädern, Turnhallen und Sportanlagen, Kommunen verlässlich unterstützen', '{3701}', 9348, 2, 2, null, 'Setzt direkt am Sanierungsstau an; Studien zeigen, dass Sportplätze und Bäder die Vereinsteilnahme stützen. Landesmittel sind aber klein gegenüber dem Rückstand in Milliardenhöhe und hängen vom Haushalt ab.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=67', 'https://www.bisp-surf.de/Record/PU201407006674', 'belegt', '2026-10-11', false, true, 'blind'),
  (9471, 37, 16, 'ST', 'Wohnortnahe Schwimmangebote mit ausreichenden Kapazitäten sicherstellen', '{3701}', null, 1, 2, null, 'Zielt auf den Erhalt wohnortnaher Bäder, nennt aber keine Mittel oder Instrumente zur Sanierung.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=67', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9472, 37, 16, 'ST', 'Vereinen ohne eigene Sportstätten Zugang ermöglichen; Zugang und Nutzung müssen finanzierbar sein', '{3702}', null, 1, 3, null, 'Benennt das Problem bezahlbarer Einmietung für Vereine ohne eigene Anlagen, lässt aber offen, wie Zugang und Kosten gesichert werden.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=68', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9473, 37, 16, 'ST', 'Ehrenamt im Sport stärken: landesweite Ehrenamtskarte, mehr Anerkennung, Vereinbarkeit mit Schule, Studium und Beruf', '{3703}', 9360, 1, 3, null, 'Würdigt Ehrenamt und erleichtert Engagement; Evaluationen zeigen Zufriedenheit der Karteninhaber, aber keinen Nachweis für mehr Engagement. Die Finanzlage der Vereine ändert sich kaum.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=68', 'https://www.baden-wuerttemberg.de/de/service/presse/pressemitteilung/pid/erprobung-der-ehrenamtskarte-laeuft-erfolgreich', 'offen', '2026-10-11', false, true, 'blind'),
  (9474, 37, 16, 'ST', 'Kooperationen von Schulen, Kitas und Vereinen unterstützen', '{3703}', 9362, 1, 3, null, 'Kann Vereinen Nachwuchs und bezahlte Ganztagsstunden bringen; belastet aber zugleich Ehrenamtliche, und die Wirkung auf die Vereinssituation ist kaum untersucht.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=68', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9475, 37, 17, null, 'Der Bund übernimmt für alle Kinder das erste Vereinsjahr im Sport per Zuschuss; soll auch die Vereine unterstützen', '{3703}', null, 1, 2, null, 'Einmaliger Zuschuss zum ersten Vereinsjahr senkt die Einstiegshürde; Sportgutscheine erreichen viele Kinder, doch viele waren schon aktiv. Danach fällt die Entlastung weg.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC7460334', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9476, 37, 17, null, 'Investitionsprogramm für kinder- und jugendfreundliche Infrastruktur, u. a. Sportstätten wohnortnah zugänglich; Mittel gegen Sanierungsstau in Bildungs- und Betreuungseinrichtungen', '{3701}', null, 1, 2, null, 'Investitionen in kommunale Infrastruktur können auch Sportstätten zugutekommen; die Mittel verteilen sich aber auf viele Einrichtungsarten, Umfang offen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=32', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9477, 37, 17, 'BE', 'Mittel für die Sanierung von Sportstätten verdoppeln und Kürzungen stoppen', '{3701}', 9348, 2, 2, null, 'Setzt direkt am Sanierungsstau an; Studien zeigen, dass Sportplätze und Bäder die Vereinsteilnahme stützen. Landesmittel sind aber klein gegenüber dem Rückstand in Milliardenhöhe und hängen vom Haushalt ab.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=27', 'https://www.bisp-surf.de/Record/PU201407006674', 'belegt', '2026-10-11', false, true, 'blind'),
  (9478, 37, 17, 'BE', 'Bei Sportstätten Instandhaltung, Umbau und barrierefreie Modernisierung vorrangig behandeln', '{3701}', 9351, 1, 3, null, 'Kann knappe Mittel auf den Bestand lenken und ist einfach umsetzbar; ändert aber nichts an der Höhe der verfügbaren Mittel.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=27', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9479, 37, 17, 'BE', 'Kommunale Sportanlagen für Vereine kostenlos oder stark vergünstigt nutzbar machen', '{3702}', 9353, 2, 2, null, 'Sportstättenkosten bestimmen laut Panelstudie die Höhe der Vereinsbeiträge, daher entlastet freie Nutzung spürbar. Die Kosten tragen aber Kommunen, deren Sportbetriebe oft schon Verluste haben; Ausgleich durch das Land nötig.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=27', 'https://www.bisp-surf.de/Record/PU202008006689', 'belegt', '2026-10-11', false, true, 'blind'),
  (9480, 37, 17, 'BE', 'Gezielte Unterstützung für Trainer, Ehrenamtliche und Inklusionsprojekte im Breitensport', '{3703}', 9358, 2, 2, null, 'Kosten für Trainer und Übungsleiter treiben laut Panelstudie die Beiträge; Zuschüsse entlasten Vereine direkt. Umfang meist unbestimmt, Finanzierung aus dem Landeshaushalt nötig.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=27', 'https://www.bisp-surf.de/Record/PU202008006689', 'belegt', '2026-10-11', false, true, 'blind'),
  (9481, 37, 17, 'MV', 'Regelmäßige Sanierung und Modernisierung bestehender Infrastruktur, darunter Sporthallen und Schwimmbäder', '{3701}', 9348, 2, 2, null, 'Setzt direkt am Sanierungsstau an; Studien zeigen, dass Sportplätze und Bäder die Vereinsteilnahme stützen. Landesmittel sind aber klein gegenüber dem Rückstand in Milliardenhöhe und hängen vom Haushalt ab.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=76', 'https://www.bisp-surf.de/Record/PU201407006674', 'belegt', '2026-10-11', false, true, 'blind'),
  (9482, 37, 17, 'MV', 'Förderung kleiner Vereine durch einen unbürokratischen Soforthilfefonds von etwa 1.000 Euro pro Verein', '{3703}', null, 1, 3, null, 'Unbürokratische Einmalhilfe erreicht kleine Vereine schnell; 1.000 Euro lindern nur kurzfristig und ändern an laufenden Kosten wenig.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=78', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9483, 37, 17, 'MV', 'Digitales Vereinsportal zur Vereinfachung von Verwaltung, Förderung und Beratung für Vereine', '{3703}', 9361, 1, 3, null, 'Bürokratie ist eine der größten Belastungen für Vereinsvorstände; Vereinfachung entlastet Ehrenamtliche. Viele Pflichten sind Bundes- oder EU-Recht, und die Wirkung auf die Vereinsfinanzen ist kaum untersucht.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=77', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9484, 37, 17, 'MV', 'Ehrenamtskarte durch eine andere Form der Würdigung ersetzen', '{3703}', 9360, 1, 3, null, 'Würdigt Ehrenamt und erleichtert Engagement; Evaluationen zeigen Zufriedenheit der Karteninhaber, aber keinen Nachweis für mehr Engagement. Die Finanzlage der Vereine ändert sich kaum.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=77', 'https://www.baden-wuerttemberg.de/de/service/presse/pressemitteilung/pid/erprobung-der-ehrenamtskarte-laeuft-erfolgreich', 'offen', '2026-10-11', false, true, 'blind'),
  (9485, 37, 17, 'ST', 'Öffentliche Investitionen in Erhalt und Neubau von Sportstätten in den kommenden Jahren', '{3701}', 9348, 2, 2, null, 'Setzt direkt am Sanierungsstau an; Studien zeigen, dass Sportplätze und Bäder die Vereinsteilnahme stützen. Landesmittel sind aber klein gegenüber dem Rückstand in Milliardenhöhe und hängen vom Haushalt ab.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=41', 'https://www.bisp-surf.de/Record/PU201407006674', 'belegt', '2026-10-11', false, true, 'blind'),
  (9486, 37, 17, 'ST', 'Vorrang für Sportstätten des Schulsports sowie für Hallen- und Freibäder', '{3701}', 9351, 1, 3, null, 'Kann knappe Mittel auf den Bestand lenken und ist einfach umsetzbar; ändert aber nichts an der Höhe der verfügbaren Mittel.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=42', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9487, 37, 17, 'ST', 'Ehrenamt im Sport stärken durch Ausweitung der Freistellung, höhere Ehrenamtspauschalen und Anerkennung bei der Rente', '{3703}', 9359, 1, 1, null, 'Kann Ehrenamt etwas attraktiver machen, eine Wirkung auf das Engagement ist aber nicht belegt; die Pauschalen wurden 2026 bereits erhöht. Regelt nur der Bund, das Land kann sich nur einsetzen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=42', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9488, 37, 17, 'ST', 'Verwaltungs- und Förderverfahren für Vereine und Verbände vereinfachen', '{3703}', 9361, 1, 3, null, 'Bürokratie ist eine der größten Belastungen für Vereinsvorstände; Vereinfachung entlastet Ehrenamtliche. Viele Pflichten sind Bundes- oder EU-Recht, und die Wirkung auf die Vereinsfinanzen ist kaum untersucht.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=42', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9489, 37, 17, 'ST', 'Bedingungen für öffentliche Förderung von Organisationen: Gemeinwohlorientierung, transparente Mittelverwendung, politische Neutralität; Gemeinnützigkeit enger fassen', '{3703}', null, 0, 2, null, 'Verschärft Förderbedingungen, ohne Mittel oder Entlastung zu bringen; kann Aufwand für Vereine erhöhen. Gemeinnützigkeit regelt das Bundessteuerrecht.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=14', null, 'offen', '2026-10-11', false, true, 'blind');

